-- C's command result describes parsing/transcript status: ordinary handler
-- failures are reported to the user but do not retain an editable prompt.
local source = vis.win
local original = source.file:content(0, source.file.size)
vis:command_register('deny', function() vis.denied = true; return false end)
assert(vis:command('deny') == true, 'C registered-handler false is not a parser failure')
assert(vis.denied)
assert(vis:command('map! insert jj') == true, 'recognized map with missing RHS')
assert(vis:command("'ap") == true, 'unset mark evaluation is handled')
assert(vis:command('1 | false') == true, 'failed shell evaluation is handled')
assert(source.file:content(0, source.file.size) == original)
assert(vis:command("#0i/'/") == true, 'apostrophe payload is structural text')
assert(source.file:content(0, source.file.size) == "'" .. original)
assert(vis:command('#0,#1d') == true)
assert(source.file:content(0, source.file.size) == original)
vis:feedkeys(':deny<Enter>')
assert(vis.win == source and vis.mode == vis.modes.NORMAL)
vis:feedkeys(":'ap<Enter>")
assert(vis.win == source and vis.mode == vis.modes.NORMAL)
vis:feedkeys(':1 | false<Enter>')
assert(vis.win == source and vis.mode == vis.modes.NORMAL)
assert(vis:command('this-command-is-unknown') == false)
vis:feedkeys(':this-command-is-unknown<Enter>')
assert(vis.win ~= source and vis.mode == vis.modes.INSERT)
vis:feedkeys('<Escape><Escape>')
assert(vis.win == source)
assert(source.file:content(0, source.file.size) == original)
